window.loadPartnerSettlementDetail=async function(o){const b=document.getElementById('partnerSettlementDetail');if(!b)return;const q=await window.sb.rpc('partner_capital_due_detail',{p_outlet:o});if(q.error){b.innerHTML='<div class="small">'+e(q.error.message)+'</div>';return;}const rows=q.data||[];let canSettle=rows.length>0;let html=rows.length?rows.map(x=>'<label style="display:block;padding:10px;border-bottom:1px solid #ddd"><input class="partner-capital-check" type="checkbox" value="'+x.stock_unit_id+'" style="width:auto"> <b>'+e(x.product_name||'Produk')+(x.variant?' — '+e(x.variant):'')+'</b><br><span class="small">'+'Warna: '+e(String(x.color||'').trim()||'Belum tercatat')+' • Modal '+m(x.capital_due)+(x.battery_health!=null?' • BH '+Number(x.battery_health)+'%':'')+(x.imei_1?' • IMEI '+e(x.imei_1):'')+'</span></label>').join(''):'<div class="small">Tidak ada modal yang belum disetor dari stok aktif.</div>';if(!rows.length&&o==='Majesty Plaza iPhone'){const h=await window.sb.from('partner_historical_stock_details').select('*').eq('outlet',o).eq('partner_name','Majesty Cell').eq('sold_status','SOLD').is('settlement_id',null).order('created_at',{ascending:true});if(h.error)html='<div class="small">Gagal mengambil rincian Plaza: '+e(h.error.message)+'</div>';else{const hr=h.data||[];canSettle=hr.length>0;html=hr.length?hr.map(x=>'<label style="display:block;padding:10px;border-bottom:1px solid #ddd"><input class="partner-capital-check partner-historical-check" type="checkbox" data-historical="1" value="'+e(x.id)+'" style="width:auto"> <b>'+e(x.product_name||'Produk')+(x.storage_gb?' — '+Number(x.storage_gb)+'GB':'')+'</b><br><span class="small">'+'Warna: '+e(String(x.color||'').trim()||'Belum tercatat')+(x.imei_1?' • IMEI '+e(x.imei_1):'')+' • Modal '+m(x.cost)+'</span></label>').join(''):'<div class="small">Tidak ada historical modal Plaza yang belum disetor.</div>';}}b.innerHTML='<div class="box"><h3>Rincian Modal '+e(o)+'</h3>'+html+(canSettle?'<div style="margin-top:12px"><button class="secondary" type="button" disabled title="Menunggu pemetaan akun kas dan utang">⏸ Settlement Ditahan Sementara</button><div class="small" style="margin-top:8px;color:#b45309">Jangan setor dari tombol ini dulu. Pemetaan akun kas dan utang belum lengkap; transaksi langsung berisiko tercatat ke akun yang salah.</div></div>':'')+'</div>';}; 
